    <div class="container">
        <div class="header">
            <h1>حجز موعد</h1>
        </div>

        <div class="doctor-section">
            <div class="doctor-avatar">د.م</div>
            <div class="doctor-info">
                <h2>د. محمد الأنصاري</h2>
                <p>أخصائي طب الأسرة</p>
            </div>
        </div>

        <div class="calendar-section">
            <div class="month-navigation">
                <button id="prev-month" aria-label="الشهر السابق">‹</button>
                <span id="month-name" class="month-name">أكتوبر 2024</span>
                <button id="next-month" aria-label="الشهر التالي">›</button>
            </div>

