                <div class="weekday">س</div>
                <div class="weekday">ج</div>
                <div class="weekday">ب</div>
                <div class="weekday">ا</div>
                <div class="weekday">خ</div>
                <div class="weekday">ث</div>
                <div class="weekday">أ</div>
            </div>

            <div id="days-grid" class="days-grid"></div>
        </div>

        <div class="time-slots-section">
            <h3>اختر وقتًا مناسبًا</h3>
            <div class="time-slots-container">
                <div class="time-slot" data-time="09:00">٩:٠٠ ص</div>
                <div class="time-slot" data-time="09:30">٩:٣٠ ص</div>
                <div class="time-slot" data-time="10:00">١٠:٠٠ ص</div>
                <div class="time-slot" data-time="10:30">١٠:٣٠ ص</div>
                <div class="time-slot" data-time="11:00">١١:٠٠ ص</div>
                <div class="time-slot" data-time="11:30">١١:٣٠ ص</div>
            </div>
        </div>

        <button id="confirm-btn" class="confirm-button" disabled>تأكيد الحجز</button>
    </div>

    <script>
        // Arabic month names
        const arabicMonths = [
            "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
            "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
        ];

        // Weekday names starting from Saturday (index 0 = Saturday)
        const arabicWeekdays = ["س", "ج", "ب", "ا", "خ", "ث", "أ"];

        let currentDate = new Date();
        let displayedMonth = currentDate.getMonth();
        let displayedYear = currentDate.getFullYear();

        const daysGrid = document.getElementById('days-grid');
        const monthNameSpan = document.getElementById('month-name');
        const prevButton = document.getElementById('prev-month');
        const nextButton = document.getElementById('next-month');
        const timeSlots = document.querySelectorAll('.time-slot');
        const confirmBtn = document.getElementById('confirm-btn');

        // Render the calendar for the given month/year
        function renderCalendar(month, year) {
            daysGrid.innerHTML = '';
            monthNameSpan.textContent = `${arabicMonths[month]} ${year}`;

            const firstDay = new Date(year, month, 1);
            const lastDay = new Date(year, month + 1, 0);
            const totalDays = lastDay.getDate();

            // Get the day of week for the first day (0=Sunday, 1=Monday, ..., 6=Saturday)
            // We need to convert to our Saturday-start system
            let startDay = firstDay.getDay();
            // Convert: Saturday=0, Sunday=1, ..., Friday=6
            // Standard JS: Sunday=0, Monday=1, ..., Saturday=6
            // So we shift: (startDay + 1) % 7 gives us Saturday=0
            startDay = (startDay + 1) % 7;

            // Add empty cells for days from the previous month
            for (let i = 0; i < startDay; i++) {
                const emptyCell = document.createElement('div');
                emptyCell.classList.add('day-cell', 'other-month');
                emptyCell.textContent = '';
                daysGrid.appendChild(emptyCell);
            }

            // Add day cells
            const today = new Date();
            const isCurrentMonth = (month === today.getMonth() && year === today.getFullYear());

            for (let day = 1; day <= totalDays; day++) {
                const dayCell = document.createElement('div');
                dayCell.classList.add('day-cell');
                dayCell.textContent = day;

                if (isCurrentMonth && day === today.getDate()) {
                    dayCell.classList.add('current-day');
                }

                dayCell.addEventListener('click', () => {
                    document.querySelectorAll('.day-cell').forEach(c => c.classList.remove('selected-day'));
                    dayCell.classList.add('selected-day');
                });

                daysGrid.appendChild(dayCell);
            }
        }

        // Time slot selection
        timeSlots.forEach(slot => {
            slot.addEventListener('click', () => {
                timeSlots.forEach(s => s.classList.remove('selected'));
                slot.classList.add('selected');
                confirmBtn.disabled = false;
            });
        });

        // Confirm button
        confirmBtn.addEventListener('click', () => {
            const selectedSlot = document.querySelector('.time-slot.selected');
            if (selectedSlot) {
                alert(`تم حجز موعد في تمام ${selectedSlot.textContent}`);
            }
        });

        // Month navigation
        prevButton.addEventListener('click', () => {
            displayedMonth--;
            if (displayedMonth < 0) {
                displayedMonth = 11;
                displayedYear--;
            }
            renderCalendar(displayedMonth, displayedYear);
        });

        nextButton.addEventListener('click', () => {
            displayedMonth++;
            if (displayedMonth > 11) {
                displayedMonth = 0;
                displayedYear++;
            }
            renderCalendar(displayedMonth, displayedYear);
        });

        // Initial render
        renderCalendar(displayedMonth, displayedYear);
    </script>
